theorem licq_multiplier_unique {m d : ℕ} {grad : Fin m → (Fin d → ℝ)} (h : LICQ grad)
    {lam₁ lam₂ : Fin m → ℝ}
    (hstat : ∑ i, (lam₁ i - lam₂ i) • grad i = 0) : lam₁ = lam₂

theorem mem_span_of_multiplier {m d : ℕ} {grad : Fin m → (Fin d → ℝ)} {gradF : Fin d → ℝ}
    (h : ∃ lam : Fin m → ℝ, ∀ j, gradF j + ∑ i, lam i * grad i j = 0) :
    gradF ∈ Submodule.span ℝ (Set.range grad)

theorem rcq_zero_combo_coeff_unique {m d : ℕ} {grad : Fin m → (Fin d → ℝ)}
    (h : LICQ grad) {lam₁ lam₂ : Fin m → ℝ}
    (hzero : ∑ i, (lam₁ i - lam₂ i) • grad i = 0) : lam₁ = lam₂

theorem rcq_sum_sub_smul_eq_zero {m d : ℕ} {grad : Fin m → (Fin d → ℝ)}
    {lam₁ lam₂ : Fin m → ℝ} (h : lam₁ = lam₂) :
    ∑ i, (lam₁ i - lam₂ i) • grad i = 0

theorem ccx_finset_sup {ι : Type*} [Fintype ι] [Nonempty ι] {s : Set ℝ} {f : ι → ℝ → ℝ}
    (hf : ∀ i, ConvexOn ℝ s (f i)) :
    ConvexOn ℝ s (fun x => Finset.univ.sup' Finset.univ_nonempty (fun i => f i x))

theorem projOn_unique_of_min {C : Set F} (hconv : Convex ℝ C) {x p q : F}
    (hpC : p ∈ C) (hqC : q ∈ C)
    (hp : ‖x - p‖ = ⨅ w : C, ‖x - w‖) (hq : ‖x - q‖ = ⨅ w : C, ‖x - w‖) : p = q

theorem concept_intent_unique (R : O → A → Prop) {O' : Set O} {B₁ B₂ : Set A}
    (h₁ : IsFormalConcept R O' B₁) (h₂ : IsFormalConcept R O' B₂) :
    B₁ = B₂

theorem concept_extent_determined (R : O → A → Prop) {O' : Set O} {B₁ B₂ : Set A}
    (h₁ : IsFormalConcept R O' B₁) (h₂ : IsFormalConcept R O' B₂) :
    extent R B₁ = extent R B₂

theorem covariant_pair_separated (R : O → A → Prop) {B : Set A} {O' : Set O}
    {a : A} (ha : a ∈ intent R O') (haB : a ∉ B) :
    ¬ (intent R O' ⊆ B)
